import{t as e}from"./api-7M9YWvHU.js";var t={async getPublicCatalog(t){return(await e.get(`/library/books`,{params:t})).data},async getBookDetails(t){return(await e.get(`/library/books/${t}`)).data},async getCategories(){return(await e.get(`/library/categories`)).data},async selfServiceCheckout(t){return(await e.post(`/library/scan/checkout`,{copy_barcode:t})).data},async selfServiceReturn(t){return(await e.post(`/library/scan/return`,{copy_barcode:t})).data},async getMyPortalData(){return(await e.get(`/library/my-loans`)).data},async renewLoan(t){return(await e.post(`/library/loans/${t}/renew`)).data},async placeHold(t){return(await e.post(`/library/books/${t}/hold`)).data},async cancelHold(t){return(await e.delete(`/library/holds/${t}`)).data}};export{t};